/*
 * This file was generated by the Gradle 'init' task.
 *
 * This project uses @Incubating APIs which are subject to change.
 */

plugins {
    `java-library`
    `maven-publish`
}

repositories {
    mavenLocal()
    maven {
        url = uri("https://repo.maven.apache.org/maven2/")
    }
}

dependencies {
    api("io.projectreactor.netty:reactor-netty:1.3.5")
    api("org.apache.httpcomponents.core5:httpcore5:5.3.1")
}

group = "io.gitee.turboweb"
version = "2.4.0-Beta2"
java.sourceCompatibility = JavaVersion.VERSION_21

publishing {
    publications.create<MavenPublication>("maven") {
        from(components["java"])
    }

    repositories {
        maven {
            name = "aliyunRDC"
            url = uri("https://packages.aliyun.com/69cb35b37c12f71e8ca5b2be/maven/luanet")

             credentials {
                 username = System.getenv("ALIYUN_REPO_USERNAME")
                 password = System.getenv("ALIYUN_REPO_PASSWORD")
             }
        }
    }
}

tasks.withType<JavaCompile>() {
    options.encoding = "UTF-8"
}

tasks.withType<Javadoc>() {
    options.encoding = "UTF-8"
}
